mapper.select:
/*selectMasterMpSoTrProgressManageList*/ SELECT Y.NUM No, --[00] Y.BUYER_NAME, --[01] Y.PO_NO, --[02] Y.GR_NO, --[03] Y.STDCATLG_ID, --[04] Y.PO_CREATE_DATE, --[05] Y.GR_DATE, --[06] Y.DELIVERY_DATE, --[07] Y.PO_QTY, --[08] Y.WMS_IVK_QTY, --[09] Y.LIST_PRICE, --[10] Y.LIST_AMT, --[11] Y.STATUS_TEXT, --[12] Y.LEGACY_PO_NO, --[13] Y.LEGACY_PO_SEQ, --[14] Y.IK_NO, --[15] Y.BUYER_ITEM_NO, --[16] Y.RD_DATE, --[17] Y.INV_DATE, --[18] Y.DOC_TEXT, --[19] Y.WMS_GR_QTY, --[20] Y.DELIVERY_QTY, --[21] Y.UNIT_PRICE, --[22] Y.UNIT_AMT, --[23] Y.DESCRIPTION, --[24] Y.SPECIFICATION, --[25] Y.AGENT, --[26] DECODE(Y.AGENT,'','0','1') AS AGENT_IMG, Y.GI_DELIVERY_QTY, --[27] Y.ADD_USER_NAME, --[28] DECODE(Y.ADD_USER_NAME,'','0','1') AS ADD_USER_NAME_IMG, Y.ADD_USER_TEL, --[29] Y.DELY_TO_LOCATION, --[30] DECODE(Y.DELY_TO_LOCATION,'','0','1') AS DELY_TO_LOCATION_IMG, Y.PO_REMARK, --[31] DECODE(Y.PO_REMARK,'','0','1') AS PO_REMARK_IMG, Y.BUYER, --[32] Y.PO_SEQ, --[33] Y.BYIT_COMORG_CODE, --[34] Y.CONTRACT_NO, --[35] Y.CONTRACT_SEQ, --[36] Y.GR_SEQ, --[37] Y.IK_SEQ, --[38] Y.PO_HD_REMARK, --[39] Y.DOC_TYPE, --[40] Y.MASTER_ITEM, --[41] Y.IMG_NO, --[42] Y.WAREHOUSE_CODE, Y.LOGISTICS_RATE, Y.LOGIS_RATE_STATUS, Y.BOX_QTY FROM ( SELECT ROWNUM NUM, X.BUYER_NAME, X.PO_NO, X.GR_NO, X.STDCATLG_ID, X.PO_CREATE_DATE, X.GR_DATE, X.DELIVERY_DATE, X.PO_QTY, X.WMS_IVK_QTY, X.LIST_PRICE, X.LIST_AMT, X.STATUS_TEXT, X.LEGACY_PO_NO, X.LEGACY_PO_SEQ, X.IK_NO, X.BUYER_ITEM_NO, X.RD_DATE, X.INV_DATE, X.DOC_TEXT, X.WMS_GR_QTY, X.DELIVERY_QTY, X.UNIT_PRICE, X.UNIT_AMT, X.DESCRIPTION, X.SPECIFICATION, X.AGENT, X.GI_DELIVERY_QTY, X.ADD_USER_NAME, X.ADD_USER_TEL, X.DELY_TO_LOCATION, X.PO_REMARK, X.BUYER, X.PO_SEQ, X.BYIT_COMORG_CODE, X.CONTRACT_NO, X.CONTRACT_SEQ, X.GR_SEQ, X.IK_SEQ, X.PO_HD_REMARK, X.DOC_TYPE, X.MASTER_ITEM, X.IMG_NO, X.WAREHOUSE_CODE, X.LOGISTICS_RATE, X.LOGIS_RATE_STATUS, X.BOX_QTY FROM ( SELECT A.BUYER_NAME AS BUYER_NAME, A.PO_NO AS PO_NO, A.GR_NO AS GR_NO, A.STDCATLG_ID AS STDCATLG_ID, A.PO_CREATE_DATE AS PO_CREATE_DATE, A.GR_DATE AS GR_DATE, A.DELIVERY_DATE AS DELIVERY_DATE, A.PO_QTY AS PO_QTY, A.WMS_IVK_QTY AS WMS_IVK_QTY, A.LIST_PRICE AS LIST_PRICE, A.LIST_AMT AS LIST_AMT, A.STATUS_TEXT AS STATUS_TEXT, A.LEGACY_PO_NO AS LEGACY_PO_NO, A.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, A.IK_NO AS IK_NO, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, A.RD_DATE AS RD_DATE, A.INV_DATE AS INV_DATE, A.DOC_TEXT AS DOC_TEXT, A.WMS_GR_QTY AS WMS_GR_QTY, A.DELIVERY_QTY AS DELIVERY_QTY, A.UNIT_PRICE AS UNIT_PRICE, A.UNIT_AMT AS UNIT_AMT, A.DESCRIPTION AS DESCRIPTION, A.SPECIFICATION AS SPECIFICATION, A.AGENT AS AGENT, A.GI_DELIVERY_QTY AS GI_DELIVERY_QTY, A.ADD_USER_NAME AS ADD_USER_NAME, A.ADD_USER_TEL AS ADD_USER_TEL, A.DELY_TO_LOCATION AS DELY_TO_LOCATION, A.PO_REMARK AS PO_REMARK, A.BUYER AS BUYER, A.PO_SEQ AS PO_SEQ, A.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, A.CONTRACT_NO AS CONTRACT_NO, A.CONTRACT_SEQ AS CONTRACT_SEQ, A.GR_SEQ AS GR_SEQ, A.IK_SEQ AS IK_SEQ, A.PO_HD_REMARK AS PO_HD_REMARK, A.DOC_TYPE AS DOC_TYPE, A.MASTER_ITEM AS MASTER_ITEM, A.IMG_NO AS IMG_NO, A.WAREHOUSE_CODE, A.LOGISTICS_RATE, A.LOGIS_RATE_STATUS, A.BOX_QTY FROM ( SELECT /*+USE_NL(PODT POHD)*/ (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.BUYER) AS BUYER_NAME, PODT.PO_NO AS PO_NO, '' AS GR_NO, DECODE(POHD.DOC_TYPE,'X',SUBSTR(PODT.BUYER_ITEM_NO,1,7), (SELECT STDCATLG_ID FROM ICOMCQDT WHERE BUYER = PODT.BYIT_COMORG_CODE AND BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND CONTRACT_NO = PODT.CONTRACT_NO AND CONTRACT_SEQ = PODT.CONTRACT_SEQ)) AS STDCATLG_ID,
POHD.PO_CREATE_DATE AS PO_CREATE_DATE, '' AS GR_DATE, '' AS DELIVERY_DATE, NVL(PODT.ITEM_QTY,0) AS PO_QTY, 0 AS WMS_IVK_QTY, NVL(PODT.AGENT_PRICE,0) AS LIST_PRICE, (NVL(PODT.ITEM_QTY,0) - NVL(PODT.DI_QTY,0)) * NVL(PODT.AGENT_PRICE,0) AS LIST_AMT, '발주' AS STATUS_TEXT, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, '' AS IK_NO, PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO, PODT.RD_DATE AS RD_DATE, '' AS INV_DATE, DECODE(PODT.PROCESS_TYPE,'1','재고','2','TR','3','VMI') ||'('|| DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반') ||')' AS DOC_TEXT, 0 AS WMS_GR_QTY, 0 AS DELIVERY_QTY, NVL(PODT.UNIT_PRICE,0) AS UNIT_PRICE, (NVL(PODT.ITEM_QTY,0) - NVL(PODT.DI_QTY,0)) * NVL(PODT.UNIT_PRICE,0) AS UNIT_AMT, PODT.DESCRIPTION AS DESCRIPTION, PODT.SPECIFICATION AS SPECIFICATION, POHD.AGENT AS AGENT, NVL(PODT.DI_QTY,0) AS GI_DELIVERY_QTY, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PODT.PO_REMARK AS PO_REMARK, POHD.BUYER AS BUYER, PODT.PO_SEQ AS PO_SEQ, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, '' AS GR_SEQ, '' AS IK_SEQ, POHD.PO_REMARK AS PO_HD_REMARK,
POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.WAREHOUSE_CODE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS, 0 AS BOX_QTY FROM ICOMPOHD POHD, ICOMPODT PODT, ICOMPRDT PRDT WHERE POHD.BUYER = PODT.BUYER AND POHD.PO_NO = PODT.PO_NO AND POHD.STATUS <> 'D' AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PODT.COMPLETE_MARK = 'N'
AND PODT.ITEM_QTY > PODT.IV_QTY
AND PODT.PROCESS_TYPE IN('1','2','3') AND PODT.WAREHOUSE_CODE =#{st_warehouse_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND 1 = 0 -- 센터입고일이 없기때문에 조회에서 제외
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER IN
#{st_buyer_code}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO = #{st_po_no})
AND PODT.PO_NO = #{st_iv_no}
AND POHD.AGENT = #{st_agent_code}
AND PODT.PO_NO like #{st_ik_no} || '%'
UNION ALL
SELECT /*+USE_NL(PODT POHD)*/ (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.BUYER) AS BUYER_NAME, PODT.PO_NO AS PO_NO, IVDT.INV_NO AS GR_NO, DECODE(POHD.DOC_TYPE,'X',SUBSTR(PODT.BUYER_ITEM_NO,1,7), (SELECT STDCATLG_ID FROM ICOMCQDT WHERE BUYER = PODT.BYIT_COMORG_CODE AND BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND CONTRACT_NO = PODT.CONTRACT_NO AND CONTRACT_SEQ = PODT.CONTRACT_SEQ)) AS STDCATLG_ID, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, IVDT.WMS_GR_DATE AS GR_DATE, '' AS DELIVERY_DATE, NVL(PODT.ITEM_QTY,0) AS PO_QTY, NVL(IVDT.WMS_IVK_QTY,0) AS WMS_IVK_QTY, NVL(PODT.AGENT_PRICE,0) AS LIST_PRICE, (NVL(IVDT.INV_QTY,0) - NVL(IVDT.WMS_GR_QTY,0)) * NVL(PODT.AGENT_PRICE,0) AS LIST_AMT, DECODE(PODT.ITEM_QTY,IVDT.INV_QTY,'입고예정','분할입고예정') AS STATUS_TEXT, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, '' AS IK_NO, PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO, PODT.RD_DATE AS RD_DATE, '' AS INV_DATE, DECODE(PODT.PROCESS_TYPE,'1','재고','2','TR','3','VMI') ||'('|| DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반')||')' AS DOC_TEXT, NVL(IVDT.WMS_GR_QTY,0) AS WMS_GR_QTY, NVL(IVDT.GR_QTY,0) AS DELIVERY_QTY, NVL(PODT.UNIT_PRICE,0) AS UNIT_PRICE, (NVL(IVDT.INV_QTY,0) - NVL(IVDT.WMS_GR_QTY,0)) * NVL(PODT.UNIT_PRICE,0) AS UNIT_AMT, PODT.DESCRIPTION AS DESCRIPTION, PODT.SPECIFICATION AS SPECIFICATION, POHD.AGENT AS AGENT, NVL(PODT.DI_QTY,0) AS GI_DELIVERY_QTY, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PODT.PO_REMARK AS PO_REMARK,
POHD.BUYER AS BUYER, PODT.PO_SEQ AS PO_SEQ, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, IVDT.INV_SEQ AS GR_SEQ, '' AS IK_SEQ, POHD.PO_REMARK AS PO_HD_REMARK,
POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.WAREHOUSE_CODE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS, 0 AS BOX_QTY FROM ICOMPOHD POHD, ICOMPODT PODT, ICOMPRDT PRDT, ICOMIVDT IVDT WHERE POHD.BUYER = PODT.BUYER AND POHD.PO_NO = PODT.PO_NO AND POHD.STATUS <> 'D' AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND IVDT.INV_QTY <> IVDT.WMS_GR_QTY AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE IN ('1','2','3') AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.WMS_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER in
#{st_buyer_code}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO = #{st_po_no})
AND IVDT.INV_NO = #{st_iv_no}
AND POHD.AGENT = #{st_agent_code}
AND PODT.PO_NO like #{st_ik_no} || '%'
UNION ALL
SELECT /*+USE_NL(PODT POHD)*/ (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.BUYER) AS BUYER_NAME, PODT.PO_NO AS PO_NO, IVDT.INV_NO AS GR_NO, DECODE(POHD.DOC_TYPE,'X',SUBSTR(PODT.BUYER_ITEM_NO,1,7), (SELECT STDCATLG_ID FROM ICOMCQDT WHERE BUYER = PODT.BYIT_COMORG_CODE AND BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND CONTRACT_NO = PODT.CONTRACT_NO AND CONTRACT_SEQ = PODT.CONTRACT_SEQ)) AS STDCATLG_ID, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, IVDT.WMS_GR_DATE AS GR_DATE, '' AS DELIVERY_DATE, NVL(PODT.ITEM_QTY,0) AS PO_QTY, 0 AS WMS_IVK_QTY, NVL(PODT.AGENT_PRICE,0) AS LIST_PRICE, (NVL(IVDT.WMS_GR_QTY,0) - NVL(IVDT.WMS_IVK_QTY,0)) * NVL(PODT.AGENT_PRICE,0) AS LIST_AMT, DECODE(IVDT.WMS_IVK_QTY,0,'출고예정','분할출고예정') AS STATUS_TEXT,
PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, '' AS IK_NO, PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO, PODT.RD_DATE AS RD_DATE, '' AS INV_DATE, DECODE(PODT.PROCESS_TYPE,'1','재고','2','TR','3','VMI') ||'('|| DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반')||')' AS DOC_TEXT, NVL(IVDT.WMS_GR_QTY,0) AS WMS_GR_QTY, NVL(IVDT.GR_QTY,0) AS DELIVERY_QTY, NVL(PODT.UNIT_PRICE,0) AS UNIT_PRICE, (NVL(IVDT.WMS_GR_QTY,0) - NVL(IVDT.WMS_IVK_QTY,0)) * NVL(PODT.UNIT_PRICE,0) AS UNIT_AMT, PODT.DESCRIPTION AS DESCRIPTION, PODT.SPECIFICATION AS SPECIFICATION, POHD.AGENT AS AGENT, NVL(PODT.DI_QTY,0) AS GI_DELIVERY_QTY, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PODT.PO_REMARK AS PO_REMARK,
POHD.BUYER AS BUYER, PODT.PO_SEQ AS PO_SEQ, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, IVDT.INV_SEQ AS GR_SEQ, '' AS IK_SEQ, POHD.PO_REMARK AS PO_HD_REMARK,
POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.WAREHOUSE_CODE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT,0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT,0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS, 0 AS BOX_QTY FROM ICOMPOHD POHD, ICOMPODT PODT, ICOMPRDT PRDT, ICOMIVDT IVDT WHERE POHD.BUYER = PODT.BUYER AND POHD.PO_NO = PODT.PO_NO AND POHD.STATUS <> 'D' AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND IVDT.WMS_GR_QTY <> IVDT.WMS_IVK_QTY AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE IN ('1','2','3') AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.WMS_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER in
#{st_buyer_code}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO = #{st_po_no})
AND IVDT.INV_NO = #{st_iv_no}
AND POHD.AGENT = #{st_agent_code}
AND PODT.PO_NO like #{st_ik_no} || '%'
UNION ALL
SELECT /*+USE_NL(PODT POHD)*/ (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.BUYER) AS BUYER_NAME, PODT.PO_NO AS PO_NO, WIDT.S_INV_NO AS GR_NO, DECODE(POHD.DOC_TYPE,'X',SUBSTR(PODT.BUYER_ITEM_NO,1,7), (SELECT STDCATLG_ID FROM ICOMCQDT WHERE BUYER = PODT.BYIT_COMORG_CODE AND BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND CONTRACT_NO = PODT.CONTRACT_NO AND CONTRACT_SEQ = PODT.CONTRACT_SEQ)) AS STDCATLG_ID, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, WIDT.GR_DATE AS GR_DATE, WIDT.DELIVERY_DATE AS DELIVERY_DATE, NVL(PODT.ITEM_QTY,0) AS PO_QTY, NVL(WIDT.INV_QTY,0) AS WMS_IVK_QTY, NVL(PODT.AGENT_PRICE,0) AS LIST_PRICE, NVL((NVL(WIDT.INV_QTY,0) * NVL(PODT.AGENT_PRICE,0)),0) AS LIST_AMT, DECODE(WIDT.INV_QTY,WIDT.DELIVERY_QTY,'배송확정',DECODE(IVDT.WMS_GR_QTY,WIDT.INV_QTY,'출고','분할출고')) AS STATUS_TEXT, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.LEGACY_PO_SEQ AS LEGACY_PO_SEQ, WIDT.INV_NO AS IK_NO, PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO, PODT.RD_DATE AS RD_DATE, WIDT.INV_DATE AS INV_DATE, DECODE(PODT.PROCESS_TYPE,'1','재고','2','TR','3','VMI') ||'('|| DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro','일반') ||')' AS DOC_TEXT, NVL(WIDT.GR_QTY,0) AS WMS_GR_QTY, NVL(WIDT.DELIVERY_QTY,0) AS DELIVERY_QTY, NVL(PODT.UNIT_PRICE,0) AS UNIT_PRICE, NVL((NVL(WIDT.INV_QTY,0) * NVL(PODT.UNIT_PRICE,0)),0) AS UNIT_AMT, PODT.DESCRIPTION AS DESCRIPTION, PODT.SPECIFICATION AS SPECIFICATION, POHD.AGENT AS AGENT, NVL(PODT.DI_QTY,0) AS GI_DELIVERY_QTY, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PODT.PO_REMARK AS PO_REMARK,
POHD.BUYER AS BUYER, PODT.PO_SEQ AS PO_SEQ, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, WIDT.S_INV_SEQ AS GR_SEQ, WIDT.INV_SEQ AS IK_SEQ, POHD.PO_REMARK AS PO_HD_REMARK,
POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.WAREHOUSE_CODE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'02', PODT.WAREHOUSE_CODE) AS LOGISTICS_RATE, F_GET_LOGISTICS_FEE_INFO(PODT.BUYER, PODT.BUYER_ITEM_NO, PODT.PROCESS_TYPE, POHD.AGENT, 0,'03', PODT.WAREHOUSE_CODE) AS LOGIS_RATE_STATUS, WIDT.BOX_QTY FROM ICOMPOHD POHD, ICOMPODT PODT, ICOMPRDT PRDT, ICOMIVDT IVDT, WMSIVDT WIDT WHERE POHD.BUYER = PODT.BUYER AND POHD.PO_NO = PODT.PO_NO AND POHD.STATUS <> 'D' AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND IVDT.BUYER = WIDT.BUYER AND IVDT.INV_NO = WIDT.S_INV_NO AND IVDT.INV_SEQ = WIDT.S_INV_SEQ AND IVDT.STATUS <> 'D' AND WIDT.STATUS <> 'D' AND PODT.PROCESS_TYPE IN ('1','2','3') AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.WMS_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER in
#{st_buyer_code}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.PO_NO = #{st_po_no} OR PODT.LEGACY_PO_NO = #{st_po_no})
AND IVDT.INV_NO = #{st_iv_no}
AND POHD.AGENT = #{st_agent_code}
AND WIDT.INV_NO LIKE #{st_ik_no} || '%'
) A
ORDER BY RD_DATE, BUYER_NAME, PO_NO, PO_SEQ
ORDER BY BUYER_NAME, PO_NO, PO_SEQ
ORDER BY AGENT, BUYER_NAME, PO_NO, PO_SEQ
ORDER BY PO_NO, PO_SEQ, BUYER_NAME
ORDER BY GR_NO, BUYER_NAME, PO_NO, PO_SEQ
ORDER BY IK_NO, BUYER_NAME, PO_NO, PO_SEQ
ORDER BY BUYER_ITEM_NO, BUYER_NAME, PO_NO, PO_SEQ
ORDER BY PO_REMARK, BUYER_NAME, PO_NO, PO_SEQ
)X
WHERE X.STATUS_TEXT IN ('발주','입고예정','분할입고예정')
WHERE X.STATUS_TEXT IN ('출고예정','분할출고예정')
WHERE X.STATUS_TEXT IN ('출고','분할출고')
WHERE X.STATUS_TEXT = #{st_status}
) Y
